"""Checks the lobby's navigation and what lives behind it: the three tabs (Play, Challenges, Profile; the special
level has its own check, tools/special_flow.py), the pages that push in over them (This week, Career, Trophies,
Stats, Wallet, Settings, How to play, Odds & fairness) and their back button, the Locker opened from Profile (equip,
try-on, its back button clears the try-on), the missions (daily on Challenges, weekly and career progress after a
run), the player card editor, the settings, the pause card, and that items already earned under the newer unlock
list are handed out on load. It also checks the free practice run (nothing is bet, recorded or earned), that
Settings holds only Sound and Vibration (the owner had the play limits removed) and the quick tour a new player
sees (it ends in a practice run; How to play reopens it), and trophy SOL (what can be claimed, the Claim key, once)."""
import asyncio, json
from playwright.async_api import async_playwright
from _paths import URL, PAGE, SHOTS, CHROME
fails = []
def check(ok, what):
    print(('ok   ' if ok else 'FAIL ') + what)
    if not ok: fails.append(what)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path=CHROME)
        ctx = await b.new_context(viewport={'width': 390, 'height': 844}, device_scale_factor=2, is_mobile=True, has_touch=True)
        page = await ctx.new_page(); errs = []
        page.on('pageerror', lambda e: errs.append(str(e)))
        await page.goto(URL); await page.wait_for_timeout(1200)
        tab = lambda: page.evaluate("document.body.dataset.tab")
        vis = lambda sel: page.evaluate(f"!document.querySelector('{sel}').classList.contains('hide')")
        check(await tab() == 'play' and await vis('#lobby'), 'opens on Play with the bet sheet')
        # tabs: Play, Challenges (today's specials and the pot), Missions (today, this week, the career), Profile (with the Locker)
        check(await page.evaluate("[...document.querySelectorAll('#tabbar [data-tab]')].map((b) => b.dataset.tab).join()") == 'play,challenges,missions,profile', 'four tabs: Play, Challenges, Missions, Profile')
        await page.click('#tabChallenges'); await page.wait_for_timeout(500)
        check(await tab() == 'challenges' and await vis('#vChallenges') and not await vis('#lobby'), 'Challenges tab shows the challenges page')
        check(await page.evaluate("!!document.querySelector('#cBody [data-page=\"special\"]') && !!document.querySelector('#cBody [data-page=\"pot\"]')"), 'Challenges has a card for today\'s special and one for the pot')
        check(await page.evaluate("document.querySelectorAll('#cBody .mrow').length") == 0 and await page.evaluate("document.querySelectorAll('#cBody .cc').length") == 3 and await page.evaluate("!!document.querySelector('#cBody .cc.du [data-page=\"duel\"]')"), 'and the duel, nothing else: the missions have their own tab')
        check(await page.evaluate("[...document.querySelectorAll('#cBody .spr-dots')].map((e) => e.children.length).join()") == '5,5,5', 'each special shows its five for the day as segments')
        await page.click('#tabMissions'); await page.wait_for_timeout(500)
        check(await tab() == 'missions' and await vis('#vMissions') and not await vis('#vChallenges'), 'Missions tab shows the missions page')
        shown = lambda: page.evaluate("[...document.querySelectorAll('#mBody .msp')].filter((e) => e.offsetParent).map((e) => e.dataset.seg).join()")
        segs = await page.evaluate("[...document.querySelectorAll('#mBody .ms-seg button')].map((b) => b.dataset.seg + ':' + b.getAttribute('aria-pressed')).join()")
        check(segs == 'day:true,week:false,career:false' and await shown() == 'day', f'Missions opens on today, with This week and Career a tap away ({segs})')
        n = await page.evaluate("document.querySelectorAll('#mBody .msp[data-seg=\"day\"] .mrow').length")
        check(n == 3, f'today lists the 3 daily missions ({n})')
        sol = await page.evaluate("document.querySelectorAll('#mBody .msp[data-seg=\"day\"] .mxp small').length")
        check(sol == 3 and await page.evaluate("document.querySelectorAll('#mBody .msp[data-seg=\"day\"] .mneed').length") == 1, f'daily missions show their SOL and the play that unlocks it ({sol})')
        await page.click('#mBody .ms-seg [data-seg="week"]'); await page.wait_for_timeout(450)
        check(await shown() == 'week' and await page.evaluate("document.querySelectorAll('#mBody .msp[data-seg=\"week\"] .mrow').length") == 3 and await page.evaluate("document.querySelectorAll('#mBody .msp[data-seg=\"week\"] .mneed').length") == 1, 'This week: 3 missions and their play bar')
        await page.click('#mBody .ms-seg [data-seg="career"]'); await page.wait_for_timeout(450)
        check(await shown() == 'career' and await page.evaluate("document.querySelectorAll('#mBody .msp[data-seg=\"career\"] .chap .mrow').length") == 4 and await page.evaluate("document.querySelectorAll('#mBody .chli').length") == 6, 'Career: the chapter, its 4 missions and the six chapters')
        check(not await page.evaluate("document.body.classList.contains('page-open')"), 'none of them opens a page')
        await page.click('#tabChallenges'); await page.wait_for_timeout(350); await page.click('#tabMissions'); await page.wait_for_timeout(450)
        check(await shown() == 'career', 'Missions remembers which one was open')
        await page.click('#mBody .ms-seg [data-seg="day"]'); await page.wait_for_timeout(300)
        await page.evaluate("document.activeElement.blur()")
        await page.keyboard.press('Space'); await page.wait_for_timeout(400)
        check(await page.evaluate('__solDunk.phase()') == 'lobby', 'Space on the Challenges tab does not start a run')
        await page.click('#tabProfile'); await page.wait_for_timeout(400)
        await page.click('#pfLocker'); await page.wait_for_timeout(600)
        check(await tab() == 'locker' and await vis('#vLocker') and await page.evaluate("document.getElementById('tabProfile').getAttribute('aria-selected')") == 'true', 'the Locker opens from Profile, under the Profile tab')
        # equip an owned ball, then try a locked one
        await page.evaluate("__solDunk.profile.owned.push('ball:retro')")
        await page.click('#lkCats [data-cat="ball"]'); await page.wait_for_timeout(200)
        await page.click('#lkGrid .item[data-id="retro"]'); await page.wait_for_timeout(300)
        check(await page.evaluate("__solDunk.profile.eq.ball") == 'retro', 'tapping an owned ball equips it')
        await page.click('#lkGrid .item[data-id="gold"]'); await page.wait_for_timeout(300)
        tr = await page.evaluate("__solDunk.nav.try")
        check(tr == {'t': 'ball', 'id': 'gold'} and await page.evaluate("__solDunk.profile.eq.ball") == 'retro', 'tapping a locked ball tries it on without equipping it')
        info = await page.evaluate("document.getElementById('lkInfo').textContent")
        check('Preview' in info and 'Legendary' in info, 'the info line says it is a preview and how rare it is')
        check(await page.evaluate("[...document.querySelectorAll('#lkCats [data-cat]')].map((b) => b.dataset.cat).join()") == 'ball,wing,trail', 'the Locker has three shelves: ball, wings and trail (the colours are fixed)')
        for cat in ['wing', 'trail']:
            await page.click(f'#lkCats [data-cat="{cat}"]'); await page.wait_for_timeout(250)
            c = await page.evaluate("document.querySelectorAll('#lkGrid .item').length")
            check(c >= 6, f'{cat} shelf has {c} items')
        check(await page.evaluate("__solDunk.nav.try") is None, 'changing shelf ends the try-on')
        await page.click('#lkGrid .item[data-id="rainbow"]'); await page.wait_for_timeout(300)
        check(await page.evaluate("__solDunk.nav.try") == {'t': 'trail', 'id': 'rainbow'}, 'tapping a locked trail tries it on')
        await page.click('#lkBack'); await page.wait_for_timeout(400)
        check(await tab() == 'profile' and await page.evaluate("__solDunk.nav.try") is None and await page.evaluate("__solDunk.profile.eq.trail") == 'classic', 'the Locker\'s back button returns to Profile and ends the try-on')
        await page.click('#pfLocker'); await page.wait_for_timeout(400)
        await page.keyboard.press('Escape'); await page.wait_for_timeout(400)
        check(await tab() == 'profile', 'Escape in the Locker goes back to Profile')
        await page.click('#tabPlay'); await page.wait_for_timeout(400)
        # pages: pushed over the current tab with a back button; one home each, no settings gear in the top bar
        pg = lambda: page.evaluate("__solDunk.nav.page")
        check(await page.evaluate("!document.getElementById('menuBtn') && !document.querySelector('#lobby .links')"), 'no settings gear in the top bar and no link row under the Play button')
        await page.click('#lobby .foot-link'); await page.wait_for_timeout(500)
        check(await pg() == 'odds' and await vis('#vPage') and await page.evaluate("document.getElementById('pgTitle').textContent") == 'Odds & fairness', 'the Odds link on the Play sheet opens Odds & fairness')
        di = await page.evaluate("__solDunk.prefs ? __solDunk.prefs.di : null")
        on = await page.evaluate("[...document.querySelectorAll('#oddsSeg button')].findIndex((b) => b.getAttribute('aria-pressed') === 'true')")
        check(di is None or on == di, f'it opens on the tier picked on the Play sheet ({on})')
        check(await page.evaluate("getComputedStyle(document.getElementById('hud')).visibility") == 'hidden', 'the top bar steps aside for the page header')
        check(await page.evaluate("document.getElementById('pgBackT').textContent") == 'Play', 'the back button names the tab underneath')
        await page.evaluate("document.activeElement.blur()")
        await page.keyboard.press('Space'); await page.wait_for_timeout(300)
        check(await page.evaluate('__solDunk.phase()') == 'lobby' and await pg() == 'odds', 'Space on a page does not start a run')
        await page.click('#pgBack'); await page.wait_for_timeout(450)
        check(await pg() is None and not await vis('#vPage') and await tab() == 'play', 'Back closes the page and shows the Play tab again')
        await page.click('#balBtn'); await page.wait_for_timeout(450)
        check(await pg() == 'wallet' and await page.evaluate("!!document.getElementById('resetBal')"), 'the balance opens the Wallet page, with the demo reset')
        await page.click('#tabPlay'); await page.wait_for_timeout(400)
        check(await pg() is None and await tab() == 'play' and await vis('#lobby'), 'tapping the current tab closes the page')
        await page.click('#tabProfile'); await page.wait_for_timeout(400)
        for k, title in [('trophies', 'Trophies'), ('stats', 'Stats'), ('wallet', 'Wallet'), ('settings', 'Settings'), ('how', 'How to play'), ('odds', 'Odds & fairness')]:
            await page.click(f'#pBody [data-page="{k}"]'); await page.wait_for_timeout(450)
            t = await page.evaluate("document.getElementById('pgTitle').textContent")
            back = await page.evaluate("document.getElementById('pgBackT').textContent")
            check(await pg() == k and t == title and back == 'Profile', f'Profile opens {title} with a way back to Profile')
            await page.keyboard.press('Escape'); await page.wait_for_timeout(400)
            check(await pg() is None and await tab() == 'profile', f'Escape closes {title}')
        snd = await page.evaluate("__solDunk.settings ? __solDunk.settings.sound : null")
        await page.click('#pBody [data-page="settings"]'); await page.wait_for_timeout(450)
        await page.click('#pgBody .switch[data-set="sound"]'); await page.wait_for_timeout(200)
        sw = await page.evaluate("document.querySelector('#pgBody .switch[data-set=\"sound\"]').getAttribute('aria-checked')")
        lbl = await page.evaluate("document.getElementById('muteBtn').getAttribute('aria-label')")
        check(sw == 'false' and lbl == 'Turn sound on', f'the Sound switch in Settings turns sound off and the mute button follows ({sw}, {lbl})')
        await page.evaluate("document.getElementById('muteBtn').click()"); await page.wait_for_timeout(200)  # it shows during runs only
        sw = await page.evaluate("document.querySelector('#pgBody .switch[data-set=\"sound\"]').getAttribute('aria-checked')")
        check(sw == 'true', 'the mute button turns it back on and the switch follows')
        await page.click('#pgBack'); await page.wait_for_timeout(400)
        bar = await page.evaluate("['balBtn', 'muteBtn'].map((id) => getComputedStyle(document.getElementById(id)).display).join()")
        check(bar.split(',')[0] != 'none' and bar.split(',')[1] == 'none', f'between runs the top bar is just the balance ({bar})')
        # profile and the card editor
        await page.click('#tabProfile'); await page.wait_for_timeout(400)
        check(await tab() == 'profile' and await vis('#vProfile'), 'the Profile tab opens the profile page')
        await page.click('#pfCard'); await page.wait_for_timeout(400)
        await page.fill('#peIn', 'Nick'); await page.dispatch_event('#peIn', 'change')
        await page.click('#panelBody [data-em="crown"]'); await page.wait_for_timeout(150)
        card = await page.evaluate("__solDunk.profile.card")
        check(card['name'] == 'Nick' and card['emblem'] == 'crown', f'player card saves name and emblem {card}')
        check(await page.evaluate("!document.querySelector('#panelBody [data-col]')"), 'the player card has no colour to pick (the colours are Solana\'s)')
        locked = await page.evaluate("document.querySelectorAll('#panelBody [data-ti][disabled]').length")
        check(locked >= 8, f'locked titles are disabled ({locked})')
        await page.click('#panelClose'); await page.wait_for_timeout(300)
        check('Nick' in await page.evaluate("document.getElementById('pBody').textContent"), 'the profile shows the new name')
        # a run: pause card, then mission progress afterwards
        await page.click('#tabPlay'); await page.wait_for_timeout(400)
        before = await page.evaluate("JSON.stringify([__solDunk.missions().weekly.map((c) => c.p), __solDunk.profile.career])")
        await page.evaluate("__solDunk.profile.tot.streak = 1; __solDunk.stats.best = 0.5")  # records this run will beat
        await page.click('#playBtn'); await page.wait_for_timeout(900)
        await page.evaluate("__solDunk.autoplay('perfect'); __solDunk.tap()"); await page.wait_for_timeout(1500)
        check(not await vis('#tabbar') or await page.evaluate("getComputedStyle(document.getElementById('tabbar')).opacity") == '0', 'the tab bar hides during a run')
        await page.click('#pauseBtn'); await page.wait_for_timeout(300)
        check(await page.evaluate('__solDunk.phase()') == 'paused' and await vis('#pauseCard'), 'pause shows the pause card')
        await page.click('#pauseCard [data-page="how"]'); await page.wait_for_timeout(450)
        check(await pg() == 'how' and await page.evaluate("document.getElementById('pgBackT').textContent") == 'Back', 'How to play opens over the paused run')
        await page.evaluate("document.activeElement.blur()")
        await page.keyboard.press('Space'); await page.wait_for_timeout(300)
        check(await page.evaluate('__solDunk.phase()') == 'paused' and await pg() == 'how', 'Space on the page does not resume the run behind it')
        await page.click('#pgBack'); await page.wait_for_timeout(450)
        check(await pg() is None and await page.evaluate('__solDunk.phase()') == 'paused' and await page.evaluate("getComputedStyle(document.getElementById('pauseCard')).opacity") == '1', 'Back returns to the pause card')
        await page.click('#resumeBtn'); await page.wait_for_timeout(1600)
        check(await page.evaluate('__solDunk.phase()') in ('play', 'clearing', 'checkpoint') and not await vis('#pauseCard'), 'Resume counts down and plays on')
        for i in range(160):
            ph = await page.evaluate('__solDunk.phase()')
            if ph in ('checkpoint', 'over'): break
            await page.wait_for_timeout(100)
        if ph == 'checkpoint':
            await page.wait_for_timeout(900); await page.click('#cashBtn'); await page.wait_for_timeout(2200)
        after = await page.evaluate("JSON.stringify([__solDunk.missions().weekly.map((c) => c.p), __solDunk.profile.career])")
        check(after != before, 'the run moved the weekly and career missions on')
        car = await page.evaluate("__solDunk.profile.career")
        check(car['p'][0] > 0 or car['ch'] > 0, f"career progress recorded {car}")
        await page.click('#lobbyBtn'); await page.wait_for_timeout(500)
        check(await tab() == 'play' and await vis('#lobby'), 'Change bet returns to the Play tab')
        # a new record gets a ticket on the result card, and Stats lists the records
        rec = await page.evaluate("[__solDunk.run.prog && __solDunk.run.prog.records, __solDunk.profile.tot, __solDunk.stats.best]")
        check(rec[0] and len(rec[0]) == 1 and rec[0][0].startswith('New record') and rec[1]['streak'] > 1, f'beating the longest streak and the best cash-out makes one new-records ticket {rec}')
        await page.click('#tabProfile'); await page.wait_for_timeout(400)
        await page.click('#pBody [data-page="stats"]'); await page.wait_for_timeout(450)
        recs = await page.evaluate("[...document.querySelectorAll('#pgBody .rec b')].map((b) => b.textContent)")
        check(len(recs) == 4 and recs[0] == str(rec[1]['streak']) and recs[3] == (str(rec[1]['perfect']) if rec[1]['perfect'] else '–'), f'Stats shows four records, the longest streak first {recs}')
        await page.click('#pgBack'); await page.wait_for_timeout(400)
        await page.click('#tabPlay'); await page.wait_for_timeout(400)
        # items earned under the newer unlock list are handed out on load
        await page.evaluate("""(() => { const p = JSON.parse(localStorage.getItem('soldunk.profile')); p.xp = 3000; p.owned = ['ball:classic', 'wing:angel', 'flame:fire']; p.fresh = []; localStorage.setItem('soldunk.profile', JSON.stringify(p)); })()""")
        await page.reload(); await page.wait_for_timeout(1200)
        owned = await page.evaluate("__solDunk.profile.owned")
        check(all(k in owned for k in ['ball:street', 'wing:aqua', 'trail:bubbles', 'ball:melon']), 'a level-15 player gets the new items for their level on load')
        check(not any(k.split(':')[0] in ('flame', 'rim', 'court') for k in owned), 'flames, rims and courts are no longer owned items')
        check(await page.evaluate("document.getElementById('badgeP').classList.contains('on')"), 'the Profile tab shows a dot for new items')
        await page.click('#tabProfile'); await page.wait_for_timeout(400)
        check(await page.evaluate("!!document.querySelector('#pfLocker .dot')"), 'and so does the Locker row on Profile')
        await page.click('#tabPlay'); await page.wait_for_timeout(400)
        # a free practice run: nothing is bet, recorded or earned
        bal0, runs0, xp0 = await page.evaluate("[__solDunk.bal(), __solDunk.stats.runs, __solDunk.profile.xp]")
        tot0 = await page.evaluate("JSON.stringify(__solDunk.profile.tot)")
        check(await page.evaluate("document.getElementById('practiceBtn').textContent") == 'Practice for free', 'a Practice for free link under the Play button')
        await page.click('#practiceBtn'); await page.wait_for_timeout(900)
        check(await page.evaluate('__solDunk.mode()') == 'practice' and await page.evaluate('__solDunk.bal()') == bal0, 'practice starts a run without taking a bet')
        await page.evaluate("__solDunk.autoplay('perfect'); __solDunk.tap()")
        for i in range(200):
            ph = await page.evaluate('__solDunk.phase()')
            if ph in ('checkpoint', 'over'): break
            await page.wait_for_timeout(100)
        if ph == 'checkpoint':
            check('practice' in (await page.evaluate("document.getElementById('cpKicker').textContent")).lower(), 'the practice checkpoint says it is practice')
            await page.wait_for_timeout(900); await page.click('#cashBtn'); await page.wait_for_timeout(2200)
        await page.evaluate("__solDunk.autoplay(null)")
        t = await page.evaluate("document.getElementById('resTitle').textContent")
        check(t.startswith('Practice'), f'the practice result says so ({t})')
        b1, r1, x1 = await page.evaluate("[__solDunk.bal(), __solDunk.stats.runs, __solDunk.profile.xp]")
        check(b1 == bal0 and r1 == runs0 and x1 == xp0, f'practice changes no balance, run count or XP ({bal0}->{b1}, {runs0}->{r1}, {xp0}->{x1})')
        check(await page.evaluate("JSON.stringify(__solDunk.profile.tot)") == tot0, 'nor the records')
        check(await page.evaluate("document.getElementById('againT').textContent") == 'Practice again' and await page.evaluate("getComputedStyle(document.getElementById('shareBtn')).display") == 'none', 'its result offers Practice again and no share')
        await page.click('#lobbyBtn'); await page.wait_for_timeout(500)
        await page.click('#tabProfile'); await page.wait_for_timeout(400)
        await page.click('#pBody [data-page="settings"]'); await page.wait_for_timeout(450)
        n = await page.evaluate("[document.querySelectorAll('#pgBody .switch').length, document.querySelectorAll('#pgBody .seg, #pgBody .sec-h').length]")
        check(n == [2, 0] and 'limit' not in (await page.evaluate("document.getElementById('pgBody').textContent")).lower(), f'Settings is just Sound and Vibration, with no play limits {n}')
        await page.click('#pgBack'); await page.wait_for_timeout(400)
        await page.click('#tabPlay'); await page.wait_for_timeout(400)
        await page.screenshot(path=SHOTS + '/ui_end.png')
        check(not errs, 'no page errors ' + json.dumps(errs))
        # the quick tour: a new player sees it once, it ends in a practice run, and How to play reopens it
        ctx2 = await b.new_context(viewport={'width': 390, 'height': 844}, device_scale_factor=2, is_mobile=True, has_touch=True)
        pg2 = await ctx2.new_page(); errs2 = []
        pg2.on('pageerror', lambda e: errs2.append(str(e)))
        await pg2.goto(PAGE); await pg2.wait_for_timeout(1500)
        tv = lambda: pg2.evaluate("!document.getElementById('tour').classList.contains('hide')")
        check(await tv() and await pg2.evaluate("document.getElementById('tourTitle').textContent") == 'Tap to fly', 'a new player sees the quick tour')
        await pg2.screenshot(path=SHOTS + '/ui_tour.png')
        await pg2.keyboard.press('Space'); await pg2.wait_for_timeout(300)
        check(await pg2.evaluate('__solDunk.phase()') == 'lobby' and await tv(), 'Space does not start a run behind the tour')
        await pg2.click('#tourNext'); await pg2.wait_for_timeout(250)
        await pg2.click('#tourNext'); await pg2.wait_for_timeout(250)
        check(await pg2.evaluate("document.getElementById('tourTitle').textContent") == 'Cash out at the green ring' and await pg2.evaluate("document.getElementById('tourNext').textContent") == 'Practice for free', 'its last step offers a practice run')
        check(await pg2.evaluate("document.querySelectorAll('#tour .tour-dots i.on').length") == 3, 'the meter fills as the tour goes on')
        await pg2.click('#tourNext'); await pg2.wait_for_timeout(900)
        check(not await tv() and await pg2.evaluate('__solDunk.mode()') == 'practice' and await pg2.evaluate("__solDunk.prefs.tourSeen") == 1, 'Practice for free closes the tour and starts a practice run')
        await pg2.evaluate("__solDunk.tap()")  # one flap, then the ball falls to the floor
        for i in range(150):
            if await pg2.evaluate("!document.getElementById('result').classList.contains('hide')"): break
            await pg2.wait_for_timeout(100)
        await pg2.click('#lobbyBtn'); await pg2.wait_for_timeout(500)
        await pg2.reload(); await pg2.wait_for_timeout(1500)
        check(not await tv(), 'the tour does not open again once seen')
        await pg2.click('#tabProfile'); await pg2.wait_for_timeout(400)
        await pg2.click('#pBody [data-page="how"]'); await pg2.wait_for_timeout(450)
        await pg2.click('#howTour'); await pg2.wait_for_timeout(700)
        check(await tv() and await pg2.evaluate("__solDunk.nav.page") is None, 'How to play reopens the tour')
        await pg2.click('#tourSkip'); await pg2.wait_for_timeout(300)
        check(not await tv() and await pg2.evaluate('__solDunk.phase()') == 'lobby', 'Skip closes it')
        check(not errs2, 'no page errors with the tour ' + json.dumps(errs2))
        # trophy SOL: each trophy pays a little SOL, claimed on the Trophies page once 0.2% of what's been bet covers it
        ctx3 = await b.new_context(viewport={'width': 390, 'height': 844}, device_scale_factor=2, is_mobile=True, has_touch=True)
        pg3 = await ctx3.new_page(); errs3 = []
        pg3.on('pageerror', lambda e: errs3.append(str(e)))
        await pg3.goto(URL); await pg3.wait_for_timeout(1200)
        tv3 = lambda: pg3.evaluate("(() => { const v = __solDunk.trophies(); return { open: v.open, claimed: v.claimed, can: v.list.filter((x) => x.can).map((x) => x.id), wait: v.list.filter((x) => x.earned && !x.claimed && !x.can).map((x) => x.id) }; })()")
        v = await tv3()
        check(v['open'] == 0 and v['claimed'] == 0 and not await pg3.evaluate("document.getElementById('badgeP').classList.contains('on')"), 'a new player has no trophy SOL to claim')
        # three trophies earned (0.001, 0.001 and 0.004 SOL) and 1 SOL bet: 0.002 SOL can be claimed, so the two small ones
        await pg3.evaluate("""(() => { const p = JSON.parse(localStorage.getItem('soldunk.profile') || '{}'), s = JSON.parse(localStorage.getItem('soldunk.stats') || '{}');
          p.ach = { swish1: 1, cp1: 1, nova5: 1 }; s.wagered = 1; localStorage.setItem('soldunk.profile', JSON.stringify(p)); localStorage.setItem('soldunk.stats', JSON.stringify(s)); })()""")
        await pg3.goto(URL); await pg3.wait_for_timeout(1200)
        v = await tv3()
        check(v['can'] == ['swish1', 'cp1'] and v['wait'] == ['nova5'], 'what has been bet opens the smallest rewards first ' + json.dumps(v))
        check(await pg3.evaluate("document.getElementById('badgeP').classList.contains('on')"), 'a dot on Profile says there is SOL to claim')
        await pg3.click('#tabProfile'); await pg3.wait_for_timeout(400)
        check(await pg3.evaluate("!!document.querySelector('#pBody [data-page=\"trophies\"] .dot')"), 'and one on the Trophies row')
        await pg3.click('#pBody [data-page="trophies"]'); await pg3.wait_for_timeout(500)
        keys = await pg3.evaluate("[...document.querySelectorAll('#pgBody [data-claim]')].map((b) => b.dataset.claim + ':' + b.textContent)")
        check(keys == ['swish1:Claim 0.001', 'cp1:Claim 0.001'], 'the Trophies page has a Claim key on each trophy that can be claimed ' + json.dumps(keys))
        txt = await pg3.evaluate("document.getElementById('pgBody').innerText")
        check('0.002 SOL to claim' in txt and 'Bet 2 more' in txt and '+250 XP' in txt and '0.025 SOL' in txt, 'and says what waits and what each trophy pays')
        await pg3.screenshot(path=SHOTS + '/ui_trophies.png')
        b0 = await pg3.evaluate('__solDunk.bal()')
        await pg3.click('#pgBody [data-claim="swish1"]'); await pg3.wait_for_timeout(400)
        b1 = await pg3.evaluate('__solDunk.bal()'); v = await tv3()
        check(abs(b1 - b0 - 0.001) < 1e-9 and v['can'] == ['cp1'] and abs(v['claimed'] - 0.001) < 1e-9, f'Claim pays the trophy\'s SOL once ({b0} -> {b1})')
        check(await pg3.evaluate("(() => { const k = document.querySelector('#pgBody [data-claim=\"swish1\"]'); return !!k && k.classList.contains('got') && k.textContent === '+0.001'; })()"), 'its key turns into what it paid')
        await pg3.wait_for_timeout(800)
        check(await pg3.evaluate("!document.querySelector('#pgBody [data-claim=\"swish1\"]')"), 'then the trophy shows it as claimed')
        await pg3.click('#pgBody [data-claim="cp1"]'); await pg3.wait_for_timeout(1200) # the key shows what it paid, then the page redraws
        v = await tv3()
        check(v['open'] == 0 and v['wait'] == ['nova5'] and abs(await pg3.evaluate('__solDunk.bal()') - b0 - 0.002) < 1e-9 and await pg3.evaluate("document.querySelectorAll('#pgBody [data-claim]').length") == 0, 'the next trophy waits until more has been bet')
        await pg3.reload(); await pg3.wait_for_timeout(1200)
        v = await tv3()
        check(abs(v['claimed'] - 0.002) < 1e-9 and v['open'] == 0 and abs(await pg3.evaluate('__solDunk.bal()') - b0 - 0.002) < 1e-9, 'claims are kept, and nothing can be claimed twice')
        check(not errs3, 'no page errors with trophy SOL ' + json.dumps(errs3))
        await b.close()
    print('FAILS', fails if fails else 'none')
asyncio.run(main())
